head.script:
scwin.checkEl = function(id) {
    if (WebSquare.wUnit.getDomById(id)) {
        return true;
    }
    return false;
}
scwin.getLog2 = function() {
    return '<list id="dataList1"><map index="0"><col1>1</col1><col2>4</col2><col3>7</col3><rowStatus statusValue="0">R</rowStatus></map><map index="1"><col1>2</col1><col2>5</col2><col3>8</col3><rowStatus statusValue="0">R</rowStatus></map><map index="2"><col1>3</col1><col2>6</col2><col3>9</col3><rowStatus statusValue="0">R</rowStatus></map></list>';
}
scwin.checktype = function() {
    return typeof popup_window_wframe;
}
scwin.checkVal = function() {
    return localStorage.getItem('log1') == scwin.getLog2();
}
scwin.checkVal2 = function() {
    return localStorage.getItem('log') == 'true';
}
scwin.checkVal3 = function() {
    debugger;
    var log2 = localStorage.getItem('log2');
    if (log2.indexOf('/web5_test/SP2/2017/uiplugin/wframe/wframe_SKT-588_(WSQ-2568)_popup_param.xml') != -1) {
        return true;
    } else {
        return false;
    }
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. main 샘플파일을 실행 후 ('CreatePopup_windows_wframe')버튼을 클릭한다.
    //1. Execute the main sample file ('CreatePopup_windows_wframe') and click the button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. popup_wframe 팝업이 보여진다.
    //1. popup_wframe popup is shown.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "object");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#popup_window_wframe_header_title').html() == 'popup_wframe'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 팝업화면의 ('isWFramePopup')를 클릭하여 실행한다.
    //2. Click on ('isWFramePopup') on the pop-up screen.
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('popup_window_wframe_wframe_trigger4')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup_window_wframe_wframe_trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 알림창에 'true' 보여진다.(wframe모드임)
    //2. 'true' is displayed in the notification window (wframe mode)
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 팝업화면의 ('getPopupParam')를 클릭하여 실행한다.
    //3. Click ('getPopupParam') on the popup screen to execute.
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('popup_window_wframe_wframe_trigger1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup_window_wframe_wframe_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 알림창에 파라미터 정보가 보여진다.
    //3. Parameter information is displayed in the notification window.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. 팝업화면의 ('getPopupUrl')를 클릭하여 실행한다.
    //4. Click ('getPopupUrl') on the pop-up screen to execute.
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('popup_window_wframe_wframe_trigger2')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup_window_wframe_wframe_trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. 알림창에 url 정보가 보여진다.
    //4. The url information is displayed in the notification window.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. 팝업화면의 ('getPopupId')를 클릭하여 실행한다.
    //5. Click ('getPopupId') on the popup screen to execute.
    WebSquare.wUnit.addCommand("assert", "scwin.checkEl('popup_window_wframe_wframe_trigger3')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup_window_wframe_wframe_trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 5. 알림창에 id 정보가 보여진다.
    //5. The id information is displayed in the notification window.
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log3') == 'popup_window_wframe'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 26-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

