requires("uiplugin.popup");       
var opts = {
    "id" : "popup_window_wframe",
    "type" :  "window",
    "width" : 300 + "px",
    "height" : 300 + "px",
    "top" : 250, 
    "left" : 250,
    "popupName" : "popup_wframe",
    "modal" : false, 
    "useIFrame" : true,
    "title" : "paramTest",
    "frameMode" : "wframe",
    "xml" : dataList1.getAllXML()
};
WebSquare.util.openPopup("wframe_SKT-588_(WSQ-2568)_popup_param.xml", opts);

